function SharedAttachment({value}:{value:any}){if(!value)return null;if(value.type==='recipe')return <div className="shared-item"><b><BookOpen size={17}/>{value.title}</b><small>{value.servings} servings · {Math.round(value.calories)} kcal each · P {Math.round(value.protein)} · C {Math.round(value.carbs)} · F {Math.round(value.fat)} g</small><div>{(value.ingredients||[]).slice(0,8).map((i:any,index:number)=><span key={index}>{i.name} · {i.grams} g</span>)}</div></div>;if(value.type==='workout_template')return <div className="shared-item"><b><Dumbbell size={17}/>{value.title}</b><small>{value.exercises.length} exercises</small><div>{value.exercises.slice(0,8).map((e:any,index:number)=><span key={index}>{e.name} · {e.sets} × {e.min}{e.max!==e.min?`–${e.max}`:''}</span>)}</div></div>;if(value.type==='song'||value.type==='recommendation')return <div className="shared-item"><b>{value.type==='song'?<Music2 size={17}/>:<Link2 size={17}/>} {value.title}</b><small>{value.artist||value.description||'Shared recommendation'}</small>{value.url&&<a href={value.url} target="_blank" rel="noopener noreferrer">Open link</a>}</div>;return <div className="shared-workout"><b><Activity size={16}/>{value.name}</b><small>{value.date} · {value.sets?.length||0} working sets</small><div>{(value.sets||[]).slice(0,8).map((s:any,i:number)=><span key={i}>{s.name} · {s.weight} kg × {s.reps}</span>)}</div></div>}
