 async function action(payload:any,quiet=false){if(isPreview){notify('This demo is read-only. Sign in to use friends and challenges.');return null;}setBusy(true);try{const r=await fetch('/api/social',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),d=await r.json() as any;if(!r.ok)throw new Error(d.error||'Action could not be saved.');await load();if(!quiet)notify('Saved.');return d;}catch(e:any){setError(e.message);notify(e.message);return null}finally{setBusy(false)}}
 async function searchPeople(e?:React.FormEvent){e?.preventDefault();const query=peopleQuery.trim().replace(/^@/,'');if(!query){setPeopleResults(data.suggestions||[]);return;}if(isPreview){setPeopleResults([]);notify('People search is available after signing in.');return;}setSearchingPeople(true);setError('');try{const r=await fetch('/api/social?q='+encodeURIComponent(query)),d=await r.json() as any;if(!r.ok)throw new Error(d.error||'Could not search people.');setPeopleResults(d.suggestions||[])}catch(e:any){setError(e.message)}finally{setSearchingPeople(false)}}
 useEffect(()=>{if(isPreview&&data.profile)demoSocialCache=data},[isPreview,data]);
