 const cleanPhoto=preparePhoto;
 function shareSnapshot(){if(shareType==='recipe'){const recipe=recipes.find(r=>r.id===shareId);if(!recipe)return null;return {type:'recipe',title:recipe.name,servings:Number(recipe.servings),calories:Number(recipe.calories),protein:Number(recipe.protein),carbs:Number(recipe.carbs),fat:Number(recipe.fat),ingredients:(recipe.ingredients||[]).map((i:any)=>({name:i.name,grams:Number(i.grams) || 0}))};}if(shareType==='workout_template'){const template=templates.find(t=>t.id===shareId);if(!template)return null;return {type:'workout_template',title:template.name,exercises:template.exercises.map(e=>({name:e.name,sets:e.sets,min:e.min,max:e.max}))};}if(shareType==='song')return shareTitle.trim()&&shareSubtitle.trim()?{type:'song',title:shareTitle.trim(),artist:shareSubtitle.trim(),url:shareUrl.trim()}:null;return shareTitle.trim()?{type:'recommendation',title:shareTitle.trim(),description:shareSubtitle.trim(),url:shareUrl.trim()}:null;}
 async function publish(e:React.FormEvent){e.preventDefault();if(isPreview){notify('Posting to friends requires signing in to the connected app.');return;}setError('');if(kind==='photo'&&!photo){setError('Choose a photo before posting.');return;}if(kind==='workout'&&!workoutId){setError('Choose a completed workout to share.');return;}const shared=kind==='share'?shareSnapshot():null;if(kind==='share'&&!shared){setError(shareType==='song'?'Add a song title and artist.':'Choose or describe something to share.');return;}setBusy(true);try{const form=new FormData();form.set('action','post');form.set('audience',audience);form.set('allowedUids',JSON.stringify(audienceUids));form.set('kind',kind);form.set('body',body);if(kind==='photo'&&photo)form.set('file',await cleanPhoto(photo));if(kind==='workout'){const w=workouts.find(x=>x.id===workoutId)!;form.set('workout',JSON.stringify({name:w.name,date:w.date,sets:shareDetails?(w.sets||[]).filter((s:any)=>s.completed&&!s.warmup).map((s:any)=>({name:s.name,weight:Number(s.weight||0),reps:Number(s.reps||0),completed:true})):[]}));}if(shared)form.set('workout',JSON.stringify(shared));const r=await fetch('/api/social',{method:'POST',body:form}),d=await r.json() as any;if(!r.ok)throw new Error(d.error||'Could not publish.');setBody('');setPhoto(null);setShareId('');setShareTitle('');setShareSubtitle('');setShareUrl('');await load();notify(audience==='private'?'Saved privately.':'Shared with your chosen audience.')}catch(e:any){setError(e.message);notify(e.message)}finally{setBusy(false)}}
 const tabs=[['feed','Feed'],['friends','Friends'],['challenges','Challenges'],['profile','My profile']] as const;
 const ownChallenge=(challenge:any)=>challenge.status==='joined';
 const inviteChallenge=async(ch:any)=>{const value=Number(baselineByChallenge[ch.id]);if(!consent||!value){setError('Enter your baseline and confirm you want to share it with challenge participants.');return;}await action({action:'challenge_join',challengeId:ch.id,baseline:value});setConsent(false);};
 const createChallenge=async(e:React.FormEvent)=>{e.preventDefault();setError('');const start=Number(baseline);if(!consent||!challengeTitle.trim()||!start||!friendSelection.length){setError('Add a title, starting value, at least one friend and confirm sharing.');return;}const result=await action({action:'challenge_create',title:challengeTitle,metric,starts,ends,baseline:start,friends:friendSelection});if(result){setChallengeTitle('');setBaseline('');setFriendSelection([]);setConsent(false)}};
 useEffect(()=>{setConsent(false);},[metric,starts,ends,baseline,friendSelection]);
